LOCALES = ["es","fr","de","pt","it","nl","tr","uk","ru","ar","hi","bn","zh","ja","id"]

def append_to_locale(code):
    path = ROOT / f"{code}.ts"
    content = path.read_text(encoding="utf-8")
    if '"newpage.title"' in content:
        print(f"  {code}: already has newpage.title, skipping")
        return
    lines = ['', '  // ── Final batch (option descriptions, pricing, chat, Pro panels, calc) ──']
    for key, per_lang in T.items():
        value = per_lang.get(code, "")
        if not value:
            value = key
        escaped = value.replace('\\', '\\\\').replace('"', '\\"')
        lines.append(f'  "{key}": "{escaped}",')
    block = "\n".join(lines) + "\n"
    if not content.rstrip().endswith("};"):
        print(f"  {code}: unexpected ending, skipping")
        return
    new = content.rstrip().rstrip("};").rstrip() + "\n" + block + "};\n"
    path.write_text(new, encoding="utf-8")
    print(f"  {code}: appended {len(T)} keys")

for code in LOCALES:
    append_to_locale(code)
print("done.")
